import { validationResult, body, param, query } from 'express-validator';

/**
 * Middleware that checks for validation errors generated by express-validator
 */
export const validate = (validations) => {
  return async (req, res, next) => {
    // Run all validations
    for (const validation of validations) {
      const result = await validation.run(req);
      if (result.errors.length) break;
    }

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    return res.status(400).json({
      success: false,
      message: errors.array()[0].msg,
      errors: errors.array()
    });
  };
};

// Common Validator Rules
export const loginValidation = [
  body('email').isEmail().withMessage('Please provide a valid email address').normalizeEmail(),
  body('password').notEmpty().withMessage('Password is required')
];

export const registerValidation = [
  body('name').trim().notEmpty().withMessage('Name is required'),
  body('email').isEmail().withMessage('Please provide a valid email address').normalizeEmail(),
  body('password').isLength({ min: 6 }).withMessage('Password must be at least 6 characters long'),
  body('role')
    .optional()
    .isIn(['super_admin', 'admin', 'principal', 'teacher', 'parent', 'student'])
    .withMessage('Invalid role provided')
];

export const studentValidation = [
  body('classGrade').notEmpty().withMessage('Class/Grade is required'),
  body('section').notEmpty().withMessage('Section is required')
];

export const attendanceValidation = [
  body('classGrade').notEmpty().withMessage('Class is required'),
  body('section').notEmpty().withMessage('Section is required'),
  body('date').isISO8601().withMessage('Valid attendance date is required'),
  body('records').isArray({ min: 1 }).withMessage('Attendance records array must not be empty')
];

export const feeValidation = [
  body('studentId').notEmpty().withMessage('Student ID is required'),
  body('dueDate').isISO8601().withMessage('Valid due date is required')
];

export const examValidation = [
  body('title').trim().notEmpty().withMessage('Exam title is required'),
  body('classGrade').notEmpty().withMessage('Class is required'),
  body('subject').notEmpty().withMessage('Subject is required'),
  body('questions').isArray({ min: 1 }).withMessage('At least one question is required')
];
